<?php require_once __DIR__.'/../../app/bootstrap.php';$d=body();$s=db()->prepare("SELECT id,name,password_hash FROM users WHERE email=? AND is_active=1");$s->execute([strtolower(trim($d['email']??''))]);$u=$s->fetch();if(!$u||!password_verify($d['password']??'',$u['password_hash']))respond(['error'=>'Invalid credentials'],401);$token=bin2hex(random_bytes(32));db()->prepare("INSERT INTO tokens(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 14 DAY))")->execute([$u['id'],hash('sha256',$token)]);respond(['token'=>$token,'user'=>['id'=>(int)$u['id'],'name'=>$u['name']]]);
